class TestFormData {constructor(form){this.values=[];for(const e of form.querySelectorAll('input,textarea,select')){const name=e.getAttribute('name');if(!name||e.disabled)continue;if(e.type==='checkbox'&&!e.checked)continue;if(e.localName==='select'){const opts=[...e.querySelectorAll('option')],chosen=opts.filter(o=>o.hasAttribute('selected'));for(const o of chosen.length?chosen:(e.hasAttribute('multiple')?[]:opts.slice(0,1)))this.values.push([name,o.getAttribute('value')??o.textContent]);}else this.values.push([name,e.value||'']);}}get(k){return this.values.find(x=>x[0]===k)?.[1]??null}getAll(k){return this.values.filter(x=>x[0]===k).map(x=>x[1])}has(k){return this.values.some(x=>x[0]===k)}entries(){return this.values[Symbol.iterator]();}}
