test('every typed record can save an edit while retaining an explicit privacy setting',async()=>{for(const item of [...app.store.state.records]){app.openEditor(item.type,item.id);const form=document.querySelector('#record-form'),privacy=form.querySelector('[name=sensitive]');assert(privacy,item.type+': missing privacy control');assert.equal(privacy.hasAttribute('checked'),Boolean(item.sensitive),item.type+': privacy setting changed while editing');privacy.checked=Boolean(item.sensitive);if(['homeChecklist','launchQA'].includes(item.type))form.querySelector('[name="data.items"]').value=(Array.isArray(item.data.items)&&item.data.items.length?item.data.items:['Acceptance check']).join('\n');if(item.type==='spread')form.querySelector('[name="data.positions"]').value=(Array.isArray(item.data.positions)&&item.data.positions.length?item.data.positions:['Position one']).join('\n');form.querySelector('[name=body]').value=(item.body||'')+' Route acceptance saved.';form.dispatchEvent(new window.Event('submit',{bubbles:true,cancelable:true}));await waitFor(()=>app.store.state.records.find(x=>x.id===item.id)?.body.includes('Route acceptance saved.'),item.type+': edited record did not persist · '+document.querySelector('#persistent-error').textContent);assert.equal(app.store.state.records.find(x=>x.id===item.id).sensitive,['lead','studioOutreach'].includes(item.type)?true:Boolean(item.sensitive),item.type+': save changed privacy classification');assert(app.store.state.records.find(x=>x.id===item.id).history.some(x=>x.body===item.body),item.type+': prior edit version was not retained');}});
