test('full JSON export is reachable and contains the current workspace state',async()=>{const privateRecord=record('account',{title:'Private export balance',sensitive:true,data:{balance:12345}});await app.store.put(privateRecord);location.hash='#settings';window.dispatchEvent(new window.Event('hashchange'));const exportButton=document.querySelector('[data-action="export"]');assert(exportButton,'JSON export action missing from Settings');let blob=null;const createElement=document.createElement.bind(document),oldCreate=URL.createObjectURL,oldRevoke=URL.revokeObjectURL;document.createElement=(name,...args)=>{const el=createElement(name,...args);if(String(name).toLowerCase()==='a')el.click=()=>{};return el;};URL.createObjectURL=value=>(blob=value,'blob:acceptance');URL.revokeObjectURL=()=>{};try{await app.handleAction({dataset:{action:'export'}});assert(blob);const output=JSON.parse(await blob.text());assert.equal(output.format,'dreamhub');assert(output.state.records.some(x=>x.id===privateRecord.id&&x.sensitive));}finally{document.createElement=createElement;URL.createObjectURL=oldCreate;URL.revokeObjectURL=oldRevoke;}});

test('failed editor persistence shows an error, keeps the draft open, and does not claim a save',async()=>{location.hash='#journal';window.dispatchEvent(new window.Event('hashchange'));app.openEditor('journal');const form=document.querySelector('#record-form');form.querySelector('[name=title]').value='Keep this unsaved page';form.querySelector('[name=body]').value='Retain these exact words.';const original=app.store.put;app.store.put=async()=>{throw Error('Simulated storage failure')};try{form.dispatchEvent(new window.Event('submit',{bubbles:true,cancelable:true}));await waitFor(()=>document.querySelector('#persistent-error').textContent.includes('Simulated storage failure'));assert.equal(document.querySelector('#editor').open,true);assert.equal(form.querySelector('[name=title]').value,'Keep this unsaved page');assert.equal(form.querySelector('[name=body]').value,'Retain these exact words.');assert(!app.store.state.records.some(x=>x.title==='Keep this unsaved page'));}finally{app.store.put=original;document.querySelector('#editor').close();}});


