 const saved=app.store.state.records.filter(x=>x.type==='event'&&x.tags.includes('Day Architect')&&x.date===date&&!x.deletedAt),taskBlock=saved.find(x=>x.data.sourceId===task.id),decision=app.store.state.records.find(x=>x.type==='scheduleDecision'&&x.title==='Day plan · '+date);assert(taskBlock?.sensitive);assert.equal(taskBlock.data.time,'09:30');assert(taskBlock.links.includes(task.id));assert(decision?.sensitive);assert(app.store.state.records.find(x=>x.id===oldBlock.id)?.deletedAt);assert.equal(app.store.state.records.find(x=>x.id===task.id).date,date);assert.equal(app.store.state.records.find(x=>x.id===shift.id).data.start,'17:00');assert.equal(app.store.state.records.find(x=>x.id===appointment.id).data.time,'13:00');await app.store.update(s=>{s.records=priorRecords;});app.render();
